def predict_next_value(n, values):
    def calculate_differences(seq):
        return [seq[i] - seq[i - 1] for i in range(1, len(seq))]

    def find_degree_of_polynomial(differences):
        if len(set(differences)) == 1:
            return 1
        else:
            return 1 + find_degree_of_polynomial(calculate_differences(differences))

    differences = values[:]
    degree = find_degree_of_polynomial(differences)

    while len(differences) > 1:
        differences = calculate_differences(differences)

    next_value = values[-1] + differences[0]
    return degree, next_value

# Example usage:
import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
values = list(map(int, data[1:]))

degree, next_value = predict_next_value(n, values)
print(degree, next_value)
